# owner: platform
"""Lay students out in seating rows, sorted by last name."""

from typing import List, Sequence, Tuple

from rosterkit.models import Student

Group = List[Student]

def _check(students: Sequence[Student], seats: int) -> None:
    if seats < 1:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")

def _sort_key(student: Student) -> Tuple[str, str]:
    last = student.last_name.lower()
    return (last, student.first_name.lower())

def _chunks(items: Group, size: int) -> List[Group]:
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]

def _format_row(number: int, group: Group) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

def _label_rows(groups: List[Group]) -> List[str]:
    pairs = enumerate(groups, start=1)
    return [_format_row(*pair) for pair in pairs]

# ---
def seat_rows(
    students: Sequence[Student],
    seats_per_row: int
) -> List[str]:
    _check(students, seats_per_row)
    ordered = sorted(students, key=_sort_key)
    return _label_rows(_chunks(ordered, seats_per_row))
